const sheet = context.workbook.worksheets.getItem("Historical χ Scorer");

// Set column widths
sheet.getRange("A:A").format.columnWidth = 200;
sheet.getRange("B:J").format.columnWidth = 40;
sheet.getRange("K:L").format.columnWidth = 45;
sheet.getRange("M:M").format.columnWidth = 80;
sheet.getRange("N:N").format.columnWidth = 70;
sheet.getRange("O:O").format.columnWidth = 55;
sheet.getRange("P:P").format.columnWidth = 95;
sheet.getRange("Q:Q").format.columnWidth = 90;

// Add conditional formatting for scores - red for negative, green for positive
const scoreRange = sheet.getRange("B23:J32");

// Red for negative scores
const redRule = scoreRange.conditionalFormats.add(Excel.ConditionalFormatType.cellValue);
redRule.cellValue.format.font.color = "#C00000";
redRule.cellValue.rule = { formula1: "0", operator: Excel.ConditionalCellValueOperator.lessThan };

// Green for positive scores
const greenRule = scoreRange.conditionalFormats.add(Excel.ConditionalFormatType.cellValue);
greenRule.cellValue.format.font.color = "#006100";
greenRule.cellValue.rule = { formula1: "0", operator: Excel.ConditionalCellValueOperator.greaterThan };

// Gray for zero
const grayRule = scoreRange.conditionalFormats.add(Excel.ConditionalFormatType.cellValue);
grayRule.cellValue.format.font.color = "#808080";
grayRule.cellValue.rule = { formula1: "0", operator: Excel.ConditionalCellValueOperator.equalTo };

// Verdict coloring
const verdictRange = sheet.getRange("P23:P32");
const destructiveRule = verdictRange.conditionalFormats.add(Excel.ConditionalFormatType.containsText);
destructiveRule.textComparison.format.font.color = "#C00000";
destructiveRule.textComparison.format.font.bold = true;
destructiveRule.textComparison.rule = { operator: Excel.ConditionalTextOperator.contains, text: "DESTRUCTIVE" };

const constructiveRule = verdictRange.conditionalFormats.add(Excel.ConditionalFormatType.containsText);
constructiveRule.textComparison.format.font.color = "#006100";
constructiveRule.textComparison.format.font.bold = true;
constructiveRule.textComparison.rule = { operator: Excel.ConditionalTextOperator.contains, text: "CONSTRUCTIVE" };

// Add thin borders to the scoring grid
sheet.getRange("A22:Q32").format.borders.getItem("InsideHorizontal").style = "Continuous";
sheet.getRange("A22:Q32").format.borders.getItem("InsideHorizontal").weight = "Thin";
sheet.getRange("A22:Q32").format.borders.getItem("InsideVertical").style = "Continuous";
sheet.getRange("A22:Q32").format.borders.getItem("InsideVertical").weight = "Thin";
sheet.getRange("A22:Q32").format.borders.getItem("EdgeBottom").style = "Continuous";
sheet.getRange("A22:Q32").format.borders.getItem("EdgeTop").style = "Continuous";
sheet.getRange("A22:Q32").format.borders.getItem("EdgeLeft").style = "Continuous";
sheet.getRange("A22:Q32").format.borders.getItem("EdgeRight").style = "Continuous";

// Freeze header row
sheet.freezePanes.freezeRows(22);

await context.sync();
return { formatted: true };

